head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[json > M > XML2JSONString]<br/>XML 데이터를 JSON 형태의 문자열로 변환하여 반환합니다.",
    "validation" : [
        "data(필수) 파라미터로 변환할 XML 데이터를 XML Document 로 설정할 수 있어야 합니다.",
        "data(필수) 파라미터로 변환할 XML 데이터를 XML 형식의 문자열로 설정할 수 있어야 합니다.",
        "XML 형식의 문자열을 전달하면 내부적으로 XML Document 로 파싱한 후 변환해야 합니다.",
        "XML 데이터를 JSON 형태로 변환한 문자열을 반환해야 합니다.",
        "data 파라미터가 XML Document 또는 XML 문자열이 아닌 경우 빈 문자열(\"\")을 반환해야 합니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};





scwin.btn_XML2JSONString_xmlDoc_onclick = function (e) {
    let xmlStr = par_data.getValue();
    let xmlDoc = WebSquare.xml.parse(xmlStr);
    let rtn = WebSquare.json.XML2JSONString(xmlDoc);
    wf_body_bottom.getObj("scwin").setReturnValue("XML2JSONString(xmlDoc) : " + rtn);
};



scwin.btn_XML2JSONString_xmlStr_onclick = function (e) {
    let xmlStr = par_data.getValue();
    let rtn = WebSquare.json.XML2JSONString(xmlStr);
    wf_body_bottom.getObj("scwin").setReturnValue("XML2JSONString(xmlStr) : " + rtn);
};



scwin.btn_XML2JSONString_invalid_onclick = function (e) {
    let rtn = WebSquare.json.XML2JSONString("invalidData");
    wf_body_bottom.getObj("scwin").setReturnValue("XML2JSONString(\"invalidData\") : \"" + rtn + "\"");
};
